import Foundation

enum DailyWallpaperText {
  static var languageIndex: Int {
    languageIndex(setting: UserDefaults.standard.string(forKey: "flutter.language"),
                  preferredLanguage: Locale.preferredLanguages.first ?? "en")
  }

  static func languageIndex(setting: String?, preferredLanguage: String) -> Int {
    switch setting {
    case "korean": return 0
    case "english": return 1
    case "japanese": return 2
    case "traditionalChinese": return 3
    default:
      let language = preferredLanguage
      if language.hasPrefix("ko") { return 0 }
      if language.hasPrefix("ja") { return 2 }
      if language.hasPrefix("zh-Hant") || language.hasPrefix("zh-TW") || language.hasPrefix("zh-HK") { return 3 }
      return 1
    }
  }

  static var locale: Locale { Locale(identifier: ["ko_KR", "en_US", "ja_JP", "zh_TW"][languageIndex]) }
  static func value(_ key: String) -> String { values[key]?[languageIndex] ?? key }

  static func automationInstructions(appName: String, language: Int = languageIndex) -> String {
    let text = { (key: String) in values[key]![language] }
    return text("helperInstructions").replacingOccurrences(of: "{app}", with: appName)
      + "\n\n" + text("helperInstructionsEnd")
  }

